INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260425_022657_4gqf', 'la', 'persona_elaine_la_1745999999', '2026-04-26T00:00:00', NULL, 'kitchen_morning', '🍳 廚房晨光', 'witty and slightly sarcastic', '集中調整型內衣', 'walk_through', '下班累,去便利商店買個御飯糰,邊走邊聊今天發生的事', NULL, '[]', 10, '09:16:00', 'fast', '720p', 'skipped', NULL, 0, NULL, 0, 'done', '欸...下班去全家買御飯糰的路上 突然想到今天開會時胸型有點跑掉 那種默默拉肩帶的尷尬你們懂吧🫠  後來換了有集中效果的內衣 整天都不用再調整了 就那個感覺...終於可以專心工作 不用一直在意自己的狀態  有時候啊 真的是這些小細節在默默影響心情 💭 存起來給需要的自己  #內衣日常 #上班族穿搭 #集中內衣 #無鋼圈內衣 #台灣MIT #設計師日常 #永康街生活 #下班後的我 #女生的小事 #舒適穿搭 #內在美學 #台北女子 #生活細節 #好內衣不貴', '下班買御飯糰的路上想到  今天開會胸型跑掉 默默拉肩帶那種尷尬   換了集中型的之後 一整天都不用再調整   就...那種終於可以專心工作 不用一直在意自己的感覺   有時候影響心情的 真的就是這些小細節啊', '欸...今天下班去便利商店買御飯糰 邊走邊想起今天開會時發生的小尷尬  就是那種 講到一半突然發現胸型有點跑掉 然後要默默拉一下肩帶 但又不能太明顯的那種時刻 你們應該懂我在說什麼🫠  我就是這種人啦 會一直在意這些小細節 然後整個下午都無法專心 一直想著等等要不要去廁所調整一下  後來換了有集中調整效果的內衣之後 真的差很多欸 就是那種...穿上去就定位了 一整天都不用再去想它的存在 可以好好專心工作 不用一直在意自己的狀態  結果呢 我發現影響工作效率的 有時候不是能力問題 而是這些看似微小但其實很重要的細節  就像今天 如果我一直在意內衣的問題 根本沒辦法好好專注在簡報上  嗯~怎麼說 好的內衣應該要讓你忘記它的存在 而不是讓你一直想著它  #內衣日常 #上班族心聲 #集中內衣 #生活細節 #台北女子  你們有沒有過那種因為內衣不舒服,整天都無法專心的經驗?', 0.006, '{}', '2026-04-24T18:26:57.246Z', '2026-04-24T18:27:24.256Z', 'active', NULL);
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260425_023235_7jrg', 'la', 'persona_elaine_la_1745999999', '2026-04-28T00:00:00', NULL, 'outdoor_garden', '🌿 戶外綠意', 'witty and slightly sarcastic', '集中調整型內衣', 'walk_through', '下班累,去便利商店買個御飯糰,邊走邊聊今天發生的事', NULL, '["https://lh3.googleusercontent.com/drive-storage/AJQWtBOOQ0uN8Hg11iEbD4pTGTIlNfWBGoG9UP6OCTI7DZyJ3_YwKXpd6BG1NzkBghP6lBKrpboXrEI3Y_MiWpkIJ99obuDvUrEWX63H-GfqhwIQILEIHA=s1200"]', 10, '09:16:00', 'fast', '720p', 'done', 'https://v3b.fal.media/files/b/0a979262/gIjZoG3ctzEmsUB07uRq5_video.mp4', 1.21, '019dc0c3-f5ad-7392-9863-65e65a724a54', 141, 'done', '欸...今天下班路上買御飯糰,突然發現一件事  走路的時候內衣不會亂跑,是一種被好好對待的感覺欸。以前那種邊走邊調整肩帶的日子,現在想起來真的很荒謬😅  就那個感覺,好像連疲憊的下班路都變得舒服一點了~  (我穿的是集中調整型的,MIT那種,質感好但不貴的款)  💾 儲存起來,給也在找好內衣的你  #下班日常 #內衣真心話 #集中內衣 #無鋼圈內衣 #台灣MIT #上班族女子 #永康街生活 #自我關愛 #好內衣不貴 #女生要對自己好 #MIT驕傲 #蕾絲內衣 #舒適穿搭', '欸...發現一件事  走路的時候內衣不會亂跑 是一種被好好對待的感覺   以前那種邊走邊調整肩帶的自己  現在想起來真的很荒謬😅', '欸...今天下班去便利商店買御飯糰 走在永康街那條我每天都會經過的小路上 突然意識到一件事  我已經好久沒有邊走路邊調整肩帶了  你們懂那種感覺嗎?以前穿某些內衣,走個十分鐘就開始不對勁。肩帶滑、下圍跑、整個人就是不舒服。然後就會一邊走一邊偷偷調整,還要確保路人看不出來,超級尷尬😅  結果呢,自從換了這件集中調整型的(MIT那種,工廠直接賣的所以不貴),我才發現原來內衣可以讓你「忘記它的存在」。不是沒感覺,是那種被好好托住、穩穩包覆的安心感。  走路不用調、彎腰不會空、連今天加班到八點的疲憊感,好像都被這件小事稀釋了一點點  就那個感覺...嗯~怎麼說 好的內衣不是讓你看起來很厲害 是讓你在疲憊的日常裡,還能好好對待自己  我就是這種人啦,會因為一件內衣穿得舒服,整個下班路都變得溫柔一點💚  你們有沒有那種「終於找到對的內衣」的瞬間?那是什麼感覺?  #下班後的小確幸 #內衣真心話 #台灣MIT', 0.006, '{}', '2026-04-24T18:32:35.969Z', '2026-04-24T18:35:06.014Z', 'active', NULL);
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260524_022215_7ogj', 'la', 'persona_elaine_la_1745999999', '2026-05-24T00:00:00', NULL, 'la_outdoor_garden', '🌿 戶外綠意', 'relaxed and playful', '機能型內衣', 'orbit', '週末天氣很好，來附近公園走走透透氣。最近這件機能型內衣真的改變我對內衣的想法——以前覺得有支撐就會悶、會勒，這件居然又包覆又透氣，走一整天都不用一直調整。素人真心分享，舒服到想跟大家講。', NULL, '["https://lh3.googleusercontent.com/drive-storage/AJQWtBPMXZ5_aSIkBvShrREs7cG8LHc_NRMgz1bHA4H4pDyRvtTvfyG-Nm91fohCqGa7gSoUDUQWqa6H6f4AL5fUVznLVhblkhjoC817qbVOMQTyGF-iLQ=s1200"]', 15, '09:16:00', 'fast', '720p', 'failed', NULL, 0, NULL, 0, 'skipped', NULL, NULL, NULL, 0, '{}', '2026-05-23T18:22:15.710Z', '2026-05-23T18:27:23.786Z', 'active', 'Timeout');
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260524_022641_ds5r', 'la', 'persona_elaine_la_1745999999', '2026-05-24T00:00:00', NULL, 'la_outdoor_garden', '🌿 戶外綠意', 'relaxed and playful', '機能型內衣', 'orbit', '週末天氣很好，來附近公園走走透透氣。最近這件機能型內衣真的改變我對內衣的想法——以前覺得有支撐就會悶、會勒，這件居然又包覆又透氣，走一整天都不用一直調整。素人真心分享，舒服到想跟大家講。', NULL, '["https://lh3.googleusercontent.com/drive-storage/AJQWtBPMXZ5_aSIkBvShrREs7cG8LHc_NRMgz1bHA4H4pDyRvtTvfyG-Nm91fohCqGa7gSoUDUQWqa6H6f4AL5fUVznLVhblkhjoC817qbVOMQTyGF-iLQ=s1200"]', 15, '09:16:00', 'fast', '720p', 'done', 'https://v3b.fal.media/files/b/0a9b6506/-xxl5f4TWa7uYad15uiJo_video.mp4', 1.21, '019e5616-f095-7022-a32c-ea86e563478f', 230, 'skipped', NULL, NULL, NULL, 0, '{}', '2026-05-23T18:26:41.522Z', '2026-05-23T18:30:35.950Z', 'active', NULL);
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260609_021849_6nfg', 'protex', 'persona_1779568973238', '2026-06-09T00:00:00', NULL, 'mountain_trail', '⛰️ 登山步道', NULL, 'PROTEX 防熊噴霧 180mL', 'walk_through', '清晨山林步道，霧氣瀰漫，鏡頭跟拍健一背影在陡峭山徑行走，突然他停下腳步，蹲下身子仔細察看地面，鏡頭特寫：泥土上有明顯的熊爪印，他抬頭看向前方密林，神情嚴肅。健一直視鏡頭自然地說:「欸，你看喔，這個爪印…。實際上啦，台灣黑熊的活動範圍這幾年一直在擴大，我跟你講，山上遇到的機率比你想的高很多」', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/protex/product/S__56508565_0_jpg-15hanGt3gRmnSveTNCUG9KF8F7nmP8HK9.jpg"]', 15, '09:16:00', 'fast', '720p', 'done', 'https://v3b.fal.media/files/b/0a9d80df/F8mTyhO74dqJu8JmCrIwk_video.mp4', 1.21, '019ea875-83c6-72a2-9c8d-ce7293b0bee4', 297, 'done', '欸，你看喔  上週帶隊玉山主峰，在排雲山莊下方 500m 發現新鮮爪痕。實際上啦，這幾年台灣黑熊目擊通報增加 40%，不是牠們變多，是活動範圍跟登山路線重疊了。  我自己腰包左側固定掛 180ml 那款，不是為了攻擊，是爭取那關鍵 15 秒逃生時間。日本規格 2.00% 辣椒素，射程 8 米，數據會說話。  安全這種事不能省，你的背包側袋現在掛什麼？  👉🏻 儲存這篇，下次上山前再確認一次  #防熊噴霧 #台灣黑熊 #登山安全 #玉山 #戶外裝備 #山岳嚮導 #BearSpray #登山必備 #野生動物安全 #高山縱走 #OutdoorSafety #台灣山林 #排雲山莊', '上週玉山，排雲下方看到爪痕  不是要嚇你  是台灣黑熊活動範圍真的在擴大   我腰包左側固定掛那罐 180ml  不為攻擊，是爭取逃生 15 秒   數據會說話： 射程 8 米 / 2.00% 辣椒素 / 日本規格   你的背包側袋，現在掛什麼？', '欸，跟你們分享一個上週的狀況。  帶隊玉山主峰那天，清晨 5 點從排雲山莊出發，走到下方大概 500 公尺的碎石坡轉彎處，我習慣性蹲下來看地面痕跡。結果發現很明顯的爪印，而且泥土還是濕的，判斷應該是凌晨 3-4 點之間留下的。  實際上啦，根據林務局這三年的通報數據，台灣黑熊目擊案例增加了將近 40%。不是熊變多了，是牠們的活動範圍跟我們常走的登山路線重疊越來越頻繁。玉山、雪山、奇萊這些熱門路線都有紀錄。  我跟你講，我自己從 2019 年開始，腰包左側就固定掛那罐 180ml 的防熊噴霧。不是要攻擊動物，是萬一真的遭遇時，能爭取那關鍵的 15 秒逃生時間。日本規格 2.00% 辣椒素濃度，射程 8 公尺，數據會說話。  安全這種事不能省。你看喔，很多人會帶登山杖、頭燈、急救包，但防熊噴霧的攜帶率還是很低。這就是差別——不是等遇到了才後悔，是要在風險發生前就準備好。  你現在的背包側袋，掛的是什麼？水壺？還是有更重要的東西？  你上山會帶防熊噴霧嗎？還是有其他防身工具？留言分享你的裝備清單  #防熊噴霧 #台灣黑熊 #登山安全 #玉山主峰 #戶外裝備', 0.006, '{}', '2026-06-08T18:18:49.556Z', '2026-06-08T18:23:53.918Z', 'active', NULL);
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260613_152313_ptd4', 'ly', 'persona_1779647108414', '2026-06-13T00:00:00', NULL, 'office', '🏢 辦公室', NULL, '焦香脆片海苔 經典原味', 'walk_through', '這包海苔有夠好吃!', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186165_jpg-1cYlhjiFGMcetHgrYRAiLke4jBof1rk9q.jpg"]', 5, '09:16:00', 'fast', '720p', 'done', 'https://v3b.fal.media/files/b/0a9e1a3a/6JstKsmU_eALj-mK-7AA9_video.mp4', 1.21, '019ebfdd-1426-79f1-a9d4-46be1517a5a1', 225, 'skipped', NULL, NULL, NULL, 0, '{}', '2026-06-13T07:23:13.489Z', '2026-06-13T07:27:04.196Z', 'active', NULL);
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260614_121323_z0ov', 'ly', 'persona_1779647108414', '2026-06-14T00:00:00', NULL, 'office', '🏢 辦公室', NULL, '焦香脆片海苔 梅子風味', 'walk_through', '這包海苔有夠好吃!', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186165_jpg-1cYlhjiFGMcetHgrYRAiLke4jBof1rk9q.jpg"]', 5, '09:16:00', 'fast', '720p', 'done', 'https://v3b.fal.media/files/b/0a9e3780/Dkej3vizw6u2mSDgEudNG_video.mp4', 1.21, '019ec455-9f32-7dd2-b180-fee21f393324', 163, 'skipped', NULL, NULL, NULL, 0, '{}', '2026-06-14T04:13:23.476Z', '2026-06-14T04:16:10.123Z', 'active', NULL);
INSERT INTO kol_episodes ("id", "brandId", "kolId", "calendar_date", "calendar_topic", "scene_id", "story_frame", "emotion", "product_name", "camera_movement", "scenario", "prompt_final", "reference_images_json", "duration", "aspect", "quality", "resolution", "video_status", "video_url", "video_cost_usd", "fal_request_id", "video_elapsed_sec", "posts_status", "post_ig", "post_threads", "post_fb", "posts_cost_usd", "engagement_json", "created_at", "updated_at", "status", "notes") VALUES ('ep_20260616_014800_hzx7', 'ly', 'persona_1779647108414', '2026-06-16T00:00:00', NULL, 'office', '🏢 辦公室', NULL, '焦香脆片海苔 梅子風味', 'walk_through', '特寫手拿著梅子風味海苔脆片包裝,鏡頭從包裝慢慢推進到又晴專注的表情,她眼睛發亮地看著鏡頭。🎭 又晴直視鏡頭自然地說:「欸我跟你說,這包海苔我真的有夠愛!梅子酸香配海苔焦脆,嗯⋯就那種一口接一口停不下來的感覺你懂嗎?」', NULL, '["https://pub-f1a2062753924a998dec046cf0f8e68a.r2.dev/ly/product/1023186165_jpg-1cYlhjiFGMcetHgrYRAiLke4jBof1rk9q.jpg"]', 15, '09:16:00', 'fast', '480p', 'done', 'https://v3b.fal.media/files/b/0a9e6c62/27lo9jzrIdi1bVh-c0672_video.mp4', 1.21, '019ecc65-cc78-7d43-b470-5c77cca0fa17', 265, 'skipped', NULL, NULL, NULL, 0, '{}', '2026-06-15T17:48:00.853Z', '2026-06-15T17:52:30.023Z', 'active', NULL);
